<script setup lang="ts">import {ref} from 'vue'; const items=[['standards','食材标准库'],['suppliers','供应商'],['plans','采购计划'],['inquiries','询价/竞价'],['orders','采购订单'],['deliveries','配送'],['inspections','智能验收'],['inventory','库存批次'],['settlements','结算']]; const user=ref(localStorage.user||''); const password=ref(localStorage.password||''); const login=()=>{localStorage.user=user.value;localStorage.password=password.value;location.reload()}; const logout=()=>{localStorage.clear();location.reload()};</script>
<template><el-config-provider><div v-if="!user" class="login"><el-card><h2>食采监管</h2><p>使用授权账户登录系统</p><el-input v-model="user" placeholder="用户名"/><el-input v-model="password" type="password" show-password placeholder="密码" @keyup.enter="login"/><el-button type="primary" @click="login">登录</el-button></el-card></div><el-container v-else><el-aside width="220px"><h2>食采监管</h2><el-menu router><el-menu-item index="/">监管驾驶舱</el-menu-item><el-menu-item v-for="x in items" :key="x[0]" :index="'/'+x[0]">{{x[1]}}</el-menu-item></el-menu></el-aside><el-container><el-header>集中采购与食品安全追溯平台 <small>当前用户：{{user}}</small><el-button text @click="logout">退出</el-button></el-header><el-main><router-view/></el-main></el-container></el-container></el-config-provider></template>
<style>body{margin:0;background:#f6f8fb;color:#24344d}h2{padding-left:20px;color:#2f6fed}.el-aside{min-height:100vh;background:white;border-right:1px solid #e6eaf0}.el-header{background:white;line-height:60px;border-bottom:1px solid #e6eaf0}small{color:#8895a7;margin-left:12px}.login{min-height:100vh;display:grid;place-items:center}.login .el-card{width:360px}.login .el-input,.login .el-button{margin-top:12px;width:100%}</style>
